customScreen.css:
:root{--accent:#4f46e5;--accent2:#818cf8;--ink:#e2e8f0;--muted:#94a3b8;--line:rgba(148,163,184,0.14);}
*{box-sizing:border-box;}html,body{margin:0;padding:0;}
body{font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;color:var(--ink);background:#0f172a;background-image:radial-gradient(1100px 520px at 12% -12%,rgba(79,70,229,0.24),transparent 60%),radial-gradient(880px 460px at 108% 4%,rgba(129,140,248,0.12),transparent 58%);background-attachment:fixed;-webkit-font-smoothing:antialiased;}
.wrap{max-width:1080px;margin:0 auto;padding:30px 22px 60px;}
.empty{text-align:center;padding:96px 20px;color:var(--muted);font-size:14px;}
.hdr{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:26px;}
.hdr-l{min-width:0;}
.eyebrow{font-size:11.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--accent2);font-weight:700;margin-bottom:7px;}
.title{margin:0;font-size:26px;line-height:1.15;font-weight:800;letter-spacing:-0.02em;color:#f8fafc;}
.who{margin-top:9px;font-size:13px;color:var(--muted);}.who b{color:#cbd5e1;font-weight:600;}
.btn{appearance:none;border:0;cursor:pointer;font:inherit;border-radius:11px;padding:11px 17px;font-weight:650;font-size:14px;}
.btn-primary{background:var(--accent);color:#fff;box-shadow:0 8px 22px -8px rgba(79,70,229,0.75);}.btn-primary:hover{filter:brightness(1.08);}
.stats{display:grid;grid-template-columns:repeat(5,1fr);gap:13px;margin-bottom:22px;}
.stat{background:rgba(30,41,59,0.6);border:1px solid var(--line);border-radius:15px;padding:16px 15px;}
.stat-val{font-size:25px;font-weight:800;letter-spacing:-0.02em;color:#f8fafc;line-height:1.1;}
.stat-label{margin-top:7px;font-size:12.5px;font-weight:600;color:#cbd5e1;}
.stat-sub{margin-top:3px;font-size:11px;color:var(--muted);}
.grid2{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:16px;}
.panel{background:rgba(30,41,59,0.5);border:1px solid var(--line);border-radius:16px;padding:18px 18px 20px;}
.panel h3{margin:0 0 15px;font-size:13.5px;font-weight:700;color:#f1f5f9;}
.bar-row{display:grid;grid-template-columns:132px 1fr 40px;align-items:center;gap:10px;margin-bottom:11px;}.bar-row:last-child{margin-bottom:0;}
.bar-name{font-size:12.5px;color:#cbd5e1;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;}
.bar-track{height:9px;border-radius:6px;background:rgba(148,163,184,0.15);overflow:hidden;}
.bar-fill{height:100%;width:0;border-radius:6px;transition:width 1s cubic-bezier(.22,1,.36,1);}
.bar-val{font-size:12.5px;font-weight:700;color:var(--ink);text-align:right;}
