.row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:11px 0;border-top:1px solid rgba(148,163,184,0.1);}.row:first-child{border-top:0;padding-top:0;}
.row-main{min-width:0;}
.row-title{font-size:13.5px;font-weight:600;color:#f1f5f9;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;}
.row-sub{margin-top:3px;font-size:11.5px;color:var(--muted);}
.row-r{text-align:right;white-space:nowrap;}
.amt{font-size:13.5px;font-weight:700;color:#f1f5f9;margin-bottom:4px;}
.badge{display:inline-block;font-size:10.5px;font-weight:700;padding:3px 9px;border-radius:999px;}
