.act .ico{width:32px;height:32px;flex:none;display:grid;place-items:center;border-radius:9px;background:rgba(79,70,229,0.18);font-size:16px;}
.empty-sm{color:var(--muted);font-size:13px;padding:12px 0;}
.empty-cta{padding-top:6px;}
