@media(max-width:900px){.stats{grid-template-columns:repeat(3,1fr);}.grid2{grid-template-columns:1fr;}}
@media(max-width:620px){.stats{grid-template-columns:repeat(2,1fr);}.act-grid{grid-template-columns:1fr 1fr;}}

